import { Component } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '[tabindex]': 'order()',
  },
})
export class PctAvatar {
  protected order(): number {
    return 0;
  }
}

const bases = () => ({ Avatar: PctAvatar });

export class PctAvatarRaised extends bases().Avatar {
  protected override order(): number {
    return 5;
  }
}
